 "chi-siamo.lead": {"it": "Dnart, il Comune e la Pro Loco di San Raffaele Cimena, dal 2022.", "en": "Dnart, the Municipality and the Pro Loco of San Raffaele Cimena, since 2022."},
 "chi-siamo.sm.0": {"it": "Cos’è il Moon Festival", "en": "What Moon Festival is"},
