 "territorio.t.0": {"it": "[DA SCRIVERE: testo sul territorio. Il sito attuale non ha una descrizione autonoma; qui sotto i passaggi già presenti in altre pagine.]", "en": "[DA SCRIVERE: testo sul territorio. Il sito attuale non ha una descrizione autonoma; qui sotto i passaggi già presenti in altre pagine.]"},
 "territorio.t.1": {"it": "Una volta all’anno San Raffaele Cimena cambia funzione. Le strade diventano percorsi, i cortili diventano scene, i balconi osservano, i muri ricevono luce, ombre, suoni e strane responsabilità poetiche.", "en": "Una volta all’anno San Raffaele Cimena cambia funzione. Le strade diventano percorsi, i cortili diventano scene, i balconi osservano, i muri ricevono luce, ombre, suoni e strane responsabilità poetiche."},
 "territorio.t.2": {"it": "Il paesaggio", "en": "Il paesaggio"},
 "territorio.t.3": {"it": "Le Moon Walk attraversano la pianura chivassese, i sentieri della Collina Torinese e il paesaggio del Parco del Po piemontese, nel territorio della Riserva della Biosfera Collina Po MAB UNESCO.", "en": "Le Moon Walk attraversano la pianura chivassese, i sentieri della Collina Torinese e il paesaggio del Parco del Po piemontese, nel territorio della Riserva della Biosfera Collina Po MAB UNESCO."},
 "territorio.t.4": {"it": "Il borgo", "en": "Il borgo"},
 "territorio.t.5": {"it": "San Raffaele Alto presenta pendenze, scalini e pavimentazioni irregolari: per arrivare e muoversi al festival trovi tutte le indicazioni in Info utili e Accessibilità.", "en": "San Raffaele Alto presenta pendenze, scalini e pavimentazioni irregolari: per arrivare e muoversi al festival trovi tutte le indicazioni in Info utili e Accessibilità."},
